:root {
  --bg0: #0b1020;
  --bg1: #1b2c4a;
  --panel: rgba(12, 18, 28, 0.74);
  --line: rgba(138, 201, 255, 0.45);
  --sky: #87d2ff;
  --grass: #4ecb67;
  --grass-dark: #2d9d4a;
  --brick: #d76835;
  --brick-dark: #a64622;
  --coin: #ffd361;
  --coin-dark: #d79d1d;
  --pipe: #4ad46a;
  --pipe-dark: #2aa64d;
  --player: #ff5d5d;
  --player-dark: #c42929;
  --enemy: #8b5a2b;
  --enemy-dark: #643818;
  --text: #edf7ff;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  min-height: 100%;
  height: 100%;
  background:
    radial-gradient(circle at top, rgba(78, 118, 255, 0.24), transparent 32%),
    linear-gradient(180deg, var(--bg0), var(--bg1) 50%, #0a111e 100%);
  color: var(--text);
  font-family: Inter, 'Segoe UI', system-ui, sans-serif;
}

body {
  display: grid;
  place-items: center;
  overflow: hidden;
}

button {
  font: inherit;
}

.app-shell {
  width: min(100vw, 1024px);
  height: min(100vh, 740px);
  padding: max(12px, env(safe-area-inset-top)) 12px max(18px, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.hud {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  padding: 12px 16px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgba(8, 14, 30, 0.76);
  box-shadow: 0 0 18px rgba(91, 175, 255, 0.12);
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 56px;
}

.label {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(233, 244, 255, 0.76);
}

.stat strong {
  font-size: clamp(1.4rem, 2vw, 2.1rem);
  color: #ffd85d;
  text-shadow: 0 0 12px rgba(255, 216, 93, 0.55);
}

.health-wrap {
  width: 100%;
}

.health-bar {
  width: min(100%, 220px);
  height: 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(141, 195, 255, 0.35);
  overflow: hidden;
  margin-top: 6px;
}

.health-fill {
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #57d55b, #ffd166, #ff6b6b);
  box-shadow: 0 0 10px rgba(87, 213, 91, 0.35);
  transition: width 0.15s ease-out;
}

.arena-wrap {
  position: relative;
  flex: 1;
  min-height: 0;
  border-radius: 20px;
  overflow: hidden;
  border: 1px solid rgba(132, 201, 255, 0.4);
  background: rgba(13, 22, 46, 0.7);
  box-shadow: inset 0 0 26px rgba(84, 157, 255, 0.12), 0 0 24px rgba(90, 150, 255, 0.12);
}

#gameCanvas {
  width: 100%;
  height: 100%;
  display: block;
  background: linear-gradient(180deg, #7cd5ff 0%, #bceaff 40%, #dff9ff 100%);
}

.overlay {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(5, 10, 18, 0.52);
  backdrop-filter: blur(4px);
}

.overlay.visible {
  display: flex;
}

.panel {
  width: min(100%, 420px);
  padding: 28px 22px 22px;
  border: 1px solid rgba(126, 197, 255, 0.45);
  border-radius: 18px;
  background: rgba(10, 16, 32, 0.82);
  box-shadow: 0 0 25px rgba(66, 122, 255, 0.18);
  text-align: center;
}

.eyebrow {
  margin: 0 0 10px;
  font-size: 0.7rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: #8fe9ff;
}

h1 {
  margin: 0;
  font-size: clamp(2rem, 4vw, 3.3rem);
  line-height: 1;
}

#overlayText {
  margin: 16px 0 22px;
  line-height: 1.6;
  color: rgba(232, 244, 255, 0.82);
}

#startButton,
.dpad-btn,
.fire-button {
  border: 1px solid rgba(120, 196, 255, 0.7);
  color: var(--text);
  background: linear-gradient(180deg, rgba(57, 94, 255, 0.24), rgba(14, 20, 49, 0.7));
  border-radius: 12px;
  box-shadow: inset 0 0 12px rgba(106, 165, 255, 0.22), 0 0 12px rgba(75, 118, 255, 0.18);
}

#startButton {
  padding: 12px 22px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
}

.touch-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 4px;
  min-height: 90px;
}

.dpad {
  position: relative;
  width: 150px;
  height: 150px;
  border-radius: 18px;
  background: rgba(9, 17, 35, 0.7);
  border: 1px solid rgba(122, 206, 255, 0.22);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  gap: 6px;
  padding: 6px;
}

.dpad-btn {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  font-size: 1.25rem;
  font-weight: 700;
  padding: 0;
  user-select: none;
  touch-action: manipulation;
}

.dpad-btn.up { grid-column: 2; grid-row: 1; }
.dpad-btn.left { grid-column: 1; grid-row: 2; }
.dpad-btn.down { grid-column: 2; grid-row: 3; }
.dpad-btn.right { grid-column: 3; grid-row: 2; }

.fire-button {
  width: min(38vw, 160px);
  min-height: 74px;
  font-size: clamp(1rem, 2.2vw, 1.5rem);
  font-weight: 800;
  letter-spacing: 0.14em;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
}

@media (max-width: 700px) {
  .app-shell {
    width: 100vw;
    padding: 8px 8px max(14px, env(safe-area-inset-bottom));
  }

  .hud {
    gap: 8px;
    padding: 10px 12px;
  }

  .touch-controls {
    padding: 0;
  }

  .dpad {
    width: 120px;
    height: 120px;
  }
}

