function drawCloud(x, y, s) {
  ctx.fillStyle = 'rgba(255,255,255,0.82)';
  ctx.beginPath();
  ctx.arc(x + 22 * s, y + 16 * s, 17 * s, Math.PI, 0);
  ctx.arc(x + 43 * s, y + 10 * s, 23 * s, Math.PI, 0);
  ctx.arc(x + 68 * s, y + 18 * s, 16 * s, Math.PI, 0);
  ctx.lineTo(x + 84 * s, y + 22 * s);
