  const x = Math.round(player.x - cameraX);
  const y = Math.round(player.y);
  const step = player.grounded ? Math.sin(player.walk) * 2 : 0;
  const squash = player.grounded ? 1 + Math.abs(player.vx) * 0.0006 : 1.06;
