  await page.screenshot({ path: '/tmp/opencode/mushroom-player-run.png' });
  const runState = await page.evaluate(() => ({ gameState, x: player.x, walk: player.walk, grounded: player.grounded }));
  await page.evaluate(() => {
    const enemy = enemies[0];
    player.x = enemy.x;
    player.y = enemy.y - player.h + 6;
    player.vy = 120;
    player.grounded = false;
  });
  await page.waitForTimeout(110);
  await page.screenshot({ path: '/tmp/opencode/mushroom-stomp.png' });
