216: function update(dt) {
217:   elapsed += dt;
218:   movePlayer(dt);
219:   cameraX = clamp(player.x - W * 0.36, 0, LEVEL_WIDTH - W);
220:   if (!player.checkpointActive && player.x + player.w >= CHECKPOINT_X) {
221:     player.checkpoint = CHECKPOINT_X + 18;
222:     player.checkpointActive = true;
223:     setMessage('Checkpoint reached!');
224:     burst(CHECKPOINT_X, GROUND_Y - 36, '#8fffc1', 12);
225:   }
226: 
227:   for (const coin of coins) {
228:     if (!coin.taken) {
229:       const bobY = coin.y + Math.sin(elapsed * 5 + coin.phase) * 4;
230:       const box = { x: coin.x - 12, y: bobY - 14, w: 24, h: 28 };
231:       if (overlap(player, box)) {
232:         coin.taken = true;
233:         player.coins += 1;
234:         burst(coin.x, bobY, '#ffd84e', 7);
235:         updateHUD();
236:       }
237:     }
238:   }
239: 
240:   for (const enemy of enemies) {
241:     if (!enemy.alive) {
242:       enemy.squishTimer = Math.max(0, enemy.squishTimer - dt);
243:       continue;
244:     }
245:     enemy.x += enemy.dir * enemy.speed * dt;
246:     if (enemy.x < enemy.min || enemy.x + enemy.w > enemy.max) enemy.dir *= -1;
247:     if (overlap(player, enemy)) {
248:       const stomp = player.vy > 80 && player.y + player.h - enemy.y < 20;
249:       if (stomp) {
250:         enemy.alive = false;
251:         enemy.squishTimer = 0.38;
252:         player.vy = -360;
253:         cameraShake = Math.max(cameraShake, 3);
254:         burst(enemy.x + enemy.w / 2, enemy.y, '#c58a53', 10);
255:       } else {
256:         loseLife();
257:       }
258:     }
259:   }
260: 
261:   if (player.x + player.w >= GOAL_X) {
262:     if (player.coins >= TARGET_COINS) {
263:       gameState = 'won';
264:       showOverlay('You made it!', `Amazing run! You grabbed ${player.coins} coins and reached the flag.`, 'Play Again');
265:     } else {
266:       setMessage(`Find ${TARGET_COINS - player.coins} more coins to unlock the flag!`);
267:       player.x = GOAL_X - player.w - 2;
268:       player.vx = 0;
269:     }
270:   }
271:   if (messageTimer > 0) messageTimer -= dt;
272:   particles = particles.filter(p => p.life > 0);
273:   for (const p of particles) {
274:     p.life -= dt;
275:     p.x += p.vx * dt;
276:     p.y += p.vy * dt;
277:     p.vy += 300 * dt;
278:   }
279: }
