508: function drawEnemy(enemy) {
509:   if (!enemy.alive && enemy.squishTimer <= 0) return;
510:   const x = enemy.x - cameraX;
511:   const squishProgress = enemy.alive ? 0 : 1 - enemy.squishTimer / 0.38;
512:   const squeeze = clamp(squishProgress / 0.18, 0, 1);
513:   const scaleY = 1 - squeeze * 0.8;
514:   const scaleX = 1 + squeeze * 0.45;
515:   const fade = enemy.alive ? 1 : clamp(enemy.squishTimer / 0.08, 0, 1);
516:   const bounce = enemy.alive ? Math.sin(elapsed * 8 + enemy.x * 0.2) * 1.5 : 0;
517:   const anchorY = enemy.y + enemy.h;
518: 
519:   ctx.save();
520:   ctx.globalAlpha *= fade;
521:   ctx.translate(x + enemy.w / 2, anchorY);
522:   ctx.scale(scaleX, scaleY);
523:   ctx.translate(-(x + enemy.w / 2), -anchorY);
524: 
525:   ctx.fillStyle = 'rgba(58,38,28,0.2)';
526:   ctx.beginPath();
527:   ctx.ellipse(x + enemy.w / 2, GROUND_Y - 1, 18, 4, 0, 0, Math.PI * 2);
528:   ctx.fill();
529: 
530:   const body = ctx.createRadialGradient(x + 12, enemy.y + 8 + bounce, 2, x + 17, enemy.y + 17 + bounce, 20);
531:   body.addColorStop(0, '#e7ac64');
532:   body.addColorStop(0.65, '#b77b3f');
533:   body.addColorStop(1, '#704322');
534:   ctx.fillStyle = body;
535:   ctx.beginPath();
536:   ctx.ellipse(x + enemy.w / 2, enemy.y + 19 + bounce, 18, 11, 0, 0, Math.PI * 2);
537:   ctx.fill();
538: 
539:   const cap = ctx.createLinearGradient(0, enemy.y + bounce, 0, enemy.y + 17 + bounce);
540:   cap.addColorStop(0, '#f0bd77');
541:   cap.addColorStop(0.55, '#c78a4c');
542:   cap.addColorStop(1, '#8a552e');
543:   ctx.fillStyle = cap;
544:   ctx.beginPath();
545:   ctx.arc(x + enemy.w / 2, enemy.y + 14 + bounce, 15, Math.PI, 0);
546:   ctx.fill();
547:   ctx.fillStyle = 'rgba(255,235,190,0.5)';
548:   ctx.beginPath();
549:   ctx.ellipse(x + 12, enemy.y + 6 + bounce, 5, 2, -0.25, 0, Math.PI * 2);
550:   ctx.fill();
551: 
552:   ctx.fillStyle = '#fff7df';
553:   ctx.fillRect(x + 9, enemy.y + 12 + bounce, 6, 8);
554:   ctx.fillRect(x + 21, enemy.y + 12 + bounce, 6, 8);
555:   ctx.fillStyle = '#30241d';
556:   ctx.fillRect(x + 12, enemy.y + 15 + bounce, 3, 4);
557:   ctx.fillRect(x + 22, enemy.y + 15 + bounce, 3, 4);
558:   ctx.fillStyle = '#fff';
559:   ctx.fillRect(x + 12, enemy.y + 15 + bounce, 1, 1);
560:   ctx.fillRect(x + 22, enemy.y + 15 + bounce, 1, 1);
561: 
562:   roundedGradientRect(x + 3, enemy.y + 24 + bounce, 12, 5, 2, '#73513a', '#35251e');
563:   roundedGradientRect(x + 21, enemy.y + 24 + bounce, 12, 5, 2, '#73513a', '#35251e');
564:   ctx.restore();
565: }
