567: function drawPlayer() {
568:   if (!player) return;
569:   if (player.invulnerable > 0 && Math.floor(elapsed * 15) % 2) return;
570: 
571:   const x = Math.round(player.x - cameraX);
572:   const y = Math.round(player.y);
573:   const speed = Math.abs(player.vx);
574:   const moving = player.grounded && speed > 18;
575:   const runAmount = moving ? clamp(speed / 170, 0, 1) : 0;
576:   const phase = player.walk;
577:   const stride = moving ? Math.sin(phase) : 0;
578:   const bob = moving ? Math.abs(Math.sin(phase * 2)) * 1.6 * runAmount : 0;
579:   const lean = moving ? clamp(player.vx / 285, -1, 1) * 0.1 : 0;
580:   const airborne = !player.grounded;
581:   const shadowY = Math.max(0, GROUND_Y - (y + player.h));
582: 
583:   ctx.fillStyle = `rgba(46,37,32,${Math.max(0.08, 0.2 - shadowY * 0.0007)})`;
584:   ctx.beginPath();
585:   ctx.ellipse(x + player.w / 2, y + player.h + 2, Math.max(7, 13 - shadowY * 0.06), 4, 0, 0, Math.PI * 2);
586:   ctx.fill();
587: 
588:   ctx.save();
589:   ctx.translate(x + player.w / 2, y + player.h / 2 + bob);
590:   ctx.scale(player.facing, 1);
591:   ctx.rotate(airborne ? (player.vy < 0 ? -0.08 : 0.07) : -lean);
592: 
593:   // Arms counter-swing against the legs to make the run cycle read clearly in profile.
594:   const armSwing = moving ? stride * 0.62 : airborne ? -0.4 : 0.08;
595:   const drawLimb = (px, py, angle, length, width, top, bottom) => {
596:     ctx.save();
597:     ctx.translate(px, py);
598:     ctx.rotate(angle);
599:     roundedGradientRect(-width / 2, 0, width, length, width / 2, top, bottom);
600:     ctx.restore();
601:   };
602: 
603:   // Far leg and shoe.
604:   drawLimb(-3, 12, airborne ? 0.65 : -stride * 0.48, 10, 5, '#3983dd', '#164c9d');
605:   drawLimb(-3 + Math.sin(phase + Math.PI) * 3 * runAmount, 19, airborne ? 0.35 : -stride * 0.75, 5, 7, '#c57545', '#63351f');
606:   // Near leg moves opposite the far leg and leads with a chunky, readable boot.
607:   drawLimb(4, 11, airborne ? -0.5 : stride * 0.48, 11, 6, '#55a5ff', '#1553b5');
608:   drawLimb(4 + Math.sin(phase) * 4 * runAmount + 2, 18, airborne ? -0.25 : stride * 0.75, 5, 8, '#b9683d', '#48251d');
609: 
610:   // Back arm, torso, and the forward arm are separate layers for a little depth.
611:   drawLimb(-7, -4, armSwing, 12, 5, '#f2bd91', '#bd7958');
612:   roundedGradientRect(-9, -4, 17, 19, 5, '#5fb0ff', '#174d9d');
613:   ctx.fillStyle = 'rgba(215,237,255,0.58)';
614:   ctx.beginPath();
615:   ctx.moveTo(-5, -1);
616:   ctx.lineTo(-2, -2);
617:   ctx.lineTo(-2, 11);
618:   ctx.lineTo(-5, 12);
619:   ctx.closePath();
620:   ctx.fill();
621:   roundedGradientRect(0, 8, 7, 7, 2, '#f8cc4f', '#ca7b21');
